using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class LowFaceAngleObstructionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Low faces pair genuine local appearances of a middle global edge, even when labels repeat.",
        H("Low-face transport and angle obstruction"),
        Blocks(
            Paragraph(Text("Let T be a finite type of tetrahedra and p an actual RawFacePairing. Its fixed-point-free involution pairs the complete face slots T times Fin 4, and its mutually inverse Fin 3 maps transport their edge slots. GlobalEdge(p) is the equivalence class generated by these identifications on T times Fin 6. The single field l assigns a real value to each such class; it is read at every local occurrence, with multiplicity.")),
            Paragraph(Text("Local(p,l,t) is the six-tuple j mapped to l(edgeLabel(p,t,j)). In BlockShape(x,h), either every entry of x is at least h, or one entry a is less than h, its opposite entry is greater than h, and the other four entries equal h. Opposite edges use the order (12,13,14,34,24,23). The short axis can be any of the six slots. A face is low when it contains a below-h entry.")),
            Paragraph(Text("Label(p,i) is edgeLabel(p,fst(i),snd(i)). Genuine(p,l,h,i) means that some local edge of tetrahedron fst(i) has value less than h. Fiber(p,e) consists of all local occurrences i with Label(p,i)=e. GenuineFiber(p,l,h,e) is its subtype satisfying Genuine(p,l,h,i). These are subtypes of local occurrences, so several edges of the same tetrahedron carrying the same global label remain distinct elements.")),
            Describe.Lean(DescribeId.Create("actual-low-face-genuine-count"),
                DeclarationHandle.Create("D5/S3/Geometry/Hyperideal/LowFaceAngleObstruction.genuine_occurrences_even"),
                H("Even genuine multiplicity on every middle edge"),
                StatementSource.FromAuthor(F.Disp(CountStatement())), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For a middle local edge in a genuine block, exactly one of its two adjacent faces contains the short opposite-axis edge. The other adjacent face contains the long axis. A block with no short edge has no low face. Consequently, projection from low face-edge flags over e to genuine local occurrences over e is a bijection.")),
                    Paragraph(Text("The original face pairing transports low flags to low flags because it preserves all three actual global edge values. It squares to the identity. A fixed low flag would project to a fixed complete face slot, contradicting the assumed fixed-point-free face pairing. The low-flag set therefore has even cardinality, as does the bijective occurrence set. This argument permits two different faces of one tetrahedron to be paired and uses no orientation or preselected normal-circle order.")))),
            Describe.Lean(DescribeId.Create("actual-low-face-angle-obstruction"),
                DeclarationHandle.Create("D5/S3/Geometry/Hyperideal/LowFaceAngleObstruction.middle_edge_angle_sum_ne_two_pi"),
                H("The middle-edge total cannot equal two pi"),
                StatementSource.FromAuthor(F.Disp(AngleStatement())), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Sum(Fiber(p,e),a) denotes the sum of a(i) over this full occurrence fiber. The hypothesis assigns each genuine appearance its own angle strictly between pi/3 and pi/2 and makes every other contribution zero. No equality of angles across a paired face is assumed. The even genuine multiplicity and the strict angle bounds exclude a total of two pi: zero terms give zero, two or four terms give less than two pi, and at least six give more than two pi.")),
                    Paragraph(Text("For the two-axis geometric family, the flat block has both axes greater than h and four zero-angle middle edges. The genuine block has a short axis below h, the opposite long axis above h and four middle edges. Section71AngleWindow supplies the strict angle interval from its precise half-angle, cotangent and Q hypotheses. The present result is the combinatorial transport and finite-sum step; a geometric application must still establish those analytic hypotheses for the same length field and its actual angles.")))),
            Paragraph(Text("The per-edge statements also permit empty T and edges with empty occurrence fibers. A nonempty collection of the two-axis blocks has a middle occurrence in every block, hence at least one actual middle global edge. Applying the angle obstruction there rules out closure on every actual edge. No conclusion is asserted for a global edge whose value differs from h or for blocks outside BlockShape.")))));

    private static Formula CountStatement()
    {
        var p = Id("p"); var l = Id("l"); var h = Id("h"); var e = Id("e");
        return Telescope(false, Imp(Conditions(p,l,h,e),
            Call("Even", Call("card", Call("GenuineFiber",p,l,h,e)))));
    }
    private static Formula AngleStatement()
    {
        var p = Id("p"); var l = Id("l"); var h = Id("h"); var e = Id("e");
        var i = Id("i"); var a = Id("a");
        var genuine = Call("Genuine",p,l,h,i);
        var angle = Apply(a,i);
        var shape = All("i",Call("Occurrence",Id("T")),
            Imp(Eq(Call("Label",p,i),e), And(
                Imp(genuine,And(Lt(new Formula.Fraction(F.Pi,F.D(3)),angle),
                    Lt(angle,new Formula.Fraction(F.Pi,F.D(2))))),
                Imp(F.Seq(F.Neg,F.Sp,genuine),Eq(angle,F.D(0))))));
        return Telescope(true, Imp(And(Conditions(p,l,h,e),shape),
            Ne(Call("Sum",Call("Fiber",p,e),a),F.Seq(F.D(2),F.Sp,F.Pi))));
    }
    private static Formula Conditions(Formula p, Formula l, Formula h, Formula e) => And(
        All("t",Id("T"),Call("BlockShape",Call("Local",p,l,Id("t")),h)),
        Eq(Apply(l,e),h));
    private static Formula Telescope(bool angle, Formula body)
    {
        var T=Id("T");var p=Id("p");
        if(angle) body=All("a",new Formula.TypeArrow(Call("Occurrence",T),Id("Real")),body);
        body=All("e",Call("GlobalEdge",p),body);
        body=All("h",Id("Real"),body);
        body=All("l",new Formula.TypeArrow(Call("GlobalEdge",p),Id("Real")),body);
        body=All("p",Call("RawFacePairing",T),body);
        return All("T",Id("Types"),F.Seq(F.OpenBracket,Call("Fintype",T),F.CloseBracket,F.Sp,body));
    }
    private static Formula Id(string s)=>F.Id(s);
    private static Formula Call(string name,params Formula[] args)=>new Formula.Apply(Id(name),[..args]);
    private static Formula Apply(Formula f,params Formula[] args)=>new Formula.Apply(f,[..args]);
    private static Formula All(string name,Formula type,Formula body)=>new Formula.Bind(FormulaQuantifier.ForAll,FormulaIdentifier.Create(name),type,body);
    private static Formula And(Formula a,Formula b)=>new Formula.Logic(a,FormulaLogicOperator.And,b);
    private static Formula Imp(Formula a,Formula b)=>new Formula.Logic(a,FormulaLogicOperator.Implies,b);
    private static Formula Eq(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Ne(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.NotEqual,b);
    private static Formula Lt(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.LessThan,b);
}
